-- [SELECT] Step: read_mplt_LKPTRANS
-- Connection: source_db
SELECT 
TA.TNCY_AGRMT_BK as TNCY_AGRMT_BK,
GRP.BLK_KEY AS BLK_KEY,
sec.ORG_UNIT_KEY as ORG_UNIT_KEY,
SEC.COST_CTR_CODE AS COST_CTR_CODE,
SEC.BSNS_ACTV_CODE AS BSNS_ACTV_CODE 
FROM 
SOR_EMS_TAM_TNCY_AGRMT TA
INNER JOIN
SOR_EMS_TAM_TNCY_AGRMT_STS TAS
ON TA.TNCY_AGRMT_KEY = TAS.TNCY_AGRMT_KEY 
INNER JOIN
SOR_HSM_UNIT UN
ON TAS.UNIT_KEY = UN.UNIT_KEY
INNER JOIN 
SOR_RVC_COST_CTR_GRP GRP
ON UN.BLK_KEY = GRP.BLK_KEY
INNER JOIN SOR_EMS_SEC_ORG_UNIT_COST_CTR SEC
ON GRP.COST_CTR_KEY = SEC.COST_CTR_KEY
WHERE GRP.COST_CTR_TYPE_CODE <> 'TPS'
AND SEC.COST_CTR_TNCY_TYPE_CODE = 'D' 
AND add_months(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1 BETWEEN GRP.BGN_DATE AND GRP.END_DATE
AND add_months(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1 BETWEEN SEC.BGN_DATE AND SEC.END_DATE
AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN TAS.BGN_DATE AND TAS.END_DATE;

-- [SELECT] Step: read_mplt_LKP_SOR_TAM_RVN_TXN
-- Connection: source_db
SELECT
SOR_TAM_RVN_TXN.CUST_KEY AS CUST_KEY,
SOR_TAM_RVN_TXN.PRH_APLY_BK_2 AS PRH_APLY_BK_2,
CASE WHEN (MAX(SOR_TAM_RVN_TXN.TXN_MTHD_CODE) <> MIN(SOR_TAM_RVN_TXN.TXN_MTHD_CODE)) THEN 'MIXED' ELSE MAX(SOR_TAM_RVN_TXN.TXN_MTHD_CODE) END AS TXN_MTHD_CODE,
MAX(SOR_TAM_RVN_TXN.EMMS_RVN_CLCT_OFFC_KEY) AS EMMS_RVN_CLCT_OFFC_KEY,
MAX(SOR_TAM_RVN_TXN.RVN_CLCT_TRML_ID) AS RVN_CLCT_TRML_ID
FROM SOR_TAM_RVN_TXN
WHERE TO_CHAR(TXN_DATE,'MM') = TO_CHAR(add_months(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1,'MM') 
AND TO_CHAR(TXN_DATE,'YYYY') = TO_CHAR(add_months(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1,'YYYY') 
AND TXN_STS_CODE IN ('S','A','P','D') 
AND TXN_MTHD_CODE in  ('OFFC_CLCT', 'OFLN', 'SYS_OFLN', 'DTD','ACCC','DRP','SWD','INTN','PHONE_BANK','ATM','ATP','PPS','FPS') 
GROUP BY SOR_TAM_RVN_TXN.CUST_KEY,SOR_TAM_RVN_TXN.PRH_APLY_BK_2;

