-- [SOURCE_QUALIFIER] Step: apply_ACTUAL_DRP
SELECT TXN_NUM, TXN_MTHD_CODE, TXN_DATE, PRH_APLY_BK_2, TXN_PYMT_ITEM_AMT, CUST_KEY FROM SOR_TAM_RVN_TXN, SOR_TAM_RVN_TXN_ITEM WHERE SOR_TAM_RVN_TXN.TXN_NUM=SOR_TAM_RVN_TXN_ITEM.TXN_NUM AND substr(to_char(SOR_TAM_RVN_TXN.TXN_DATE, 'YYYYMMDD'), 1, 6) = $$v_rpt_mth AND SOR_TAM_RVN_TXN.TXN_STS_CODE IN ('S', 'A', 'P', 'D') and SOR_TAM_RVN_TXN.TXN_MTHD_CODE in ('DRP', 'SWD');

-- [SELECT] Step: read_LKP_UAO_FEE_ADV_AMT
-- Connection: SSA
select LPAD(CUST_KEY,9,'0') || LPAD(HSE_SRVC_APLY_KEY,15,'0') as TNCY_AGRMT_BK,
sum(FRST_ADV_UAO_FEE_PYMT_CF_AMT+SCND_ADV_UAO_FEE_PYMT_CF_AMT+THRD_ADV_UAO_FEE_PYMT_CF_AMT) as ADV_UAO_FEE_PYMT_CF_AMT
from SOR_EMS_MRRS_ADV_UAO_FEE_CF
where SYS_RPT_YEAR = to_number(substr('$$v_rpt_mth',1,4))
and SYS_RPT_MTH =to_number(substr('$$v_rpt_mth',5,2))
group by LPAD(CUST_KEY,9,'0') || LPAD(HSE_SRVC_APLY_KEY,15,'0');

-- [SELECT] Step: read_LKP_UAO_FEE_ARR_AMT
-- Connection: SOR
select LPAD(CUST_KEY,9,'0') || LPAD(HSE_SRVC_APLY_KEY,15,'0') as TNCY_AGRMT_BK,
sum(FRST_UAO_FEE_ARR_CF_AMT+SCND_UAO_FEE_ARR_CF_AMT+THRD_UAO_FEE_ARR_CF_AMT+FRTH_UAO_FEE_ARR_CF_AMT+FTH_UAO_FEE_ARR_CF_AMT+SXTH_UAO_FEE_ARR_CF_AMT+SVNTH_UAO_FEE_ARR_CF_AMT+EGHTH_UAO_FEE_ARR_CF_AMT+NTH_UAO_FEE_ARR_CF_AMT) as UAO_FEE_ARR_CF_AMT
from SOR_EMS_MRRS_UAO_FEE_ARR_CF
where SYS_RPT_YEAR = to_number(substr('$$v_rpt_mth',1,4))
and SYS_RPT_MTH =to_number(substr('$$v_rpt_mth',5,2))
group by LPAD(CUST_KEY,9,'0') || LPAD(HSE_SRVC_APLY_KEY,15,'0');

-- [SELECT] Step: read_LKP_MTH_RENT
-- Connection: SSA
SELECT LPAD(CUST_KEY,9,'0') || LPAD(HSE_SRVC_APLY_KEY,15,'0') as TNCY_AGRMT_BK,
sum(UNIT_GRS_RENT_AMT + TNT_ADTN_RENT_AMT - TNT_RDC_RENT_AMT) as MTH_RENT
FROM SOR_EMS_SRP_MRRS_RENT_RCV 
WHERE SYS_RPT_YEAR = to_number(substr('$$v_rpt_mth',1,4))
and SYS_RPT_MTH =to_number(substr('$$v_rpt_mth',5,2))
group by LPAD(CUST_KEY,9,'0') || LPAD(HSE_SRVC_APLY_KEY,15,'0');

-- [SELECT] Step: read_LKP_SOR_EMS_TAM_TNCY_AGRMT_STS
-- Connection: SOR
select	
	TNCY_AGRMT_BK as TNCY_AGRMT_BK, 
	max(TNCY_AGRMT_TM_STS_CODE) as TNCY_AGRMT_TM_STS_CODE,
	max(RENT_FCTR_CODE) as RENT_FCTR_CODE,
	max(TNCY_AGRMT_CMNC_DATE) as TNCY_AGRMT_CMNC_DATE,
	max(TNCY_AGRMT_TM_TRMT_DATE) as TNCY_AGRMT_TM_TRMT_DATE
from (
select 
tncy_agrmt_Bk AS TNCY_AGRMT_BK, 	
null as TNCY_AGRMT_TM_STS_CODE,
null as RENT_RVW_CATG_CODE, 
RENT_FCTR_CODE as RENT_FCTR_CODE,
null as TNCY_AGRMT_CMNC_DATE,
null as TNCY_AGRMT_TM_TRMT_DATE
from sor_ems_tam_tncy_agrmt t,
sor_ems_tam_tncy_agrmt_sts t1,(
select tncy_agrmt_key, max(end_date) as end_date
from sor_ems_tam_tncy_agrmt_sts
where ( to_date($$v_snsh_date,'yyyymmdd') > end_date or  to_date($$v_snsh_date,'yyyymmdd') between bgn_date and end_date) and 
rent_bgn_date <= add_months(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1
group by tncy_agrmt_key) t2
where t.tncy_agrmt_key = t1.tncy_agrmt_key and
t2.tncy_agrmt_key = t1.tncy_agrmt_key and t2.end_date = t1.end_date
union all
SELECT  
	TNCY_AGRMT_BK as TNCY_AGRMT_BK,
	SOR_EMS_TAM_TNCY_AGRMT_STS.TNCY_AGRMT_TM_STS_CODE as TNCY_AGRMT_TM_STS_CODE,
	null as RENT_RVW_CATG_CODE, 	
	null as RENT_FCTR_CODE,
	SOR_EMS_TAM_TNCY_AGRMT_STS.TNCY_AGRMT_CMNC_DATE as TNCY_AGRMT_CMNC_DATE,
	SOR_EMS_TAM_TNCY_AGRMT_STS.TNCY_AGRMT_TM_TRMT_DATE as TNCY_AGRMT_TM_TRMT_DATE
FROM 
	SOR_EMS_TAM_TNCY_AGRMT,
	SOR_EMS_TAM_TNCY_AGRMT_STS
WHERE 
	SOR_EMS_TAM_TNCY_AGRMT.tncy_agrmt_key =	SOR_EMS_TAM_TNCY_AGRMT_STS.tncy_agrmt_key
and (TO_DATE('$$v_snsh_date', 'YYYYMMDD') ) BETWEEN SOR_EMS_TAM_TNCY_AGRMT_STS.BGN_DATE AND SOR_EMS_TAM_TNCY_AGRMT_STS.END_DATE 
) 
group by 
	TNCY_AGRMT_BK;

-- [SELECT] Step: read_LKP_MSN_PRFT_ARR_AMT
-- Connection: SSA
select LPAD(CUST_KEY,9,'0') || LPAD(HSE_SRVC_APLY_KEY,15,'0') as TNCY_AGRMT_BK,
sum(FRST_MSN_PRFT_ARR_CF_AMT+SCND_MSN_PRFT_ARR_CF_AMT+THRD_MSN_PRFT_ARR_CF_AMT+FRTH_MSN_PRFT_ARR_CF_AMT+FTH_MSN_PRFT_ARR_CF_AMT+SXTH_MSN_PRFT_ARR_CF_AMT+SVNTH_MSN_PRFT_ARR_CF_AMT+EGHTH_MSN_PRFT_ARR_CF_AMT+NTH_MSN_PRFT_ARR_CF_AMT) as MSN_PRFT_ARR_CF_AMT 
from SOR_EMS_MRRS_MSN_PRFT_ARR_CF
where SYS_RPT_YEAR = to_number(substr('$$v_rpt_mth',1,4))
and SYS_RPT_MTH =to_number(substr('$$v_rpt_mth',5,2))
group by LPAD(CUST_KEY,9,'0') || LPAD(HSE_SRVC_APLY_KEY,15,'0');

