sum(FRST_RENT_ARR_CF_AMT+SCND_RENT_ARR_CF_AMT+THRD_RENT_ARR_CF_AMT+FRTH_RENT_ARR_CF_AMT+FTH_RENT_ARR_CF_AMT+SXTH_RENT_ARR_CF_AMT+SVNTH_RENT_ARR_CF_AMT+EGHTH_RENT_ARR_CF_AMT+NTH_RENT_ARR_CF_AMT) as RENT_ARR_CF_AMT 
