-- [SELECT] Step: read_LKP_MSN_PRFT_ADV_AMT
-- Connection: SSA
select LPAD(CUST_KEY,9,'0') || LPAD(HSE_SRVC_APLY_KEY,15,'0') as TNCY_AGRMT_BK,
sum(FRST_ADV_MSN_PRFT_PYMT_CF_AMT+SCND_ADV_MSN_PRFT_PYMT_CF_AMT+THRD_ADV_MSN_PRFT_PYMT_CF_AMT) as ADV_MSN_PRFT_PYMT_CF_AMT
