-- [SELECT] Step: read_LKP_RATE_CNCSN
-- Connection: SSA
SELECT LPAD(CUST_KEY,9,'0') || LPAD(HSE_SRVC_APLY_KEY,15,'0') as TNCY_AGRMT_BK, SUM(RATS.RATE_CNCSN_AMT) as RATE_CNCSN_AMT
      FROM    SOR_EMS_RWV_RATE_CNCSN_REC  RAT, SOR_EMS_RWV_RATE_CNCSN_REC_STS  RATS
        WHERE   RATS.RATE_CNCSN_EXRC_STS_CODE = 'A'
		AND 	RAT.RATE_CNCSN_KEY = RATS.RATE_CNCSN_KEY
        AND     RATS.RATE_CNCSN_TYPE_CODE IN ('5')
        AND     RATS.RATE_CNCSN_BGN_DATE  <= ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1)-1
        AND     RATS.RATE_CNCSN_END_DATE  >= ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1)-1   
AND RATS.BGN_DATE <= TO_DATE('$$v_snsh_date', 'YYYYMMDD')
AND RATS.END_DATE >= TO_DATE('$$v_snsh_date', 'YYYYMMDD')
 GROUP BY LPAD(CUST_KEY,9,'0') || LPAD(HSE_SRVC_APLY_KEY,15,'0');

-- [SELECT] Step: read_LKP_RENT_WVE
-- Connection: SSA
SELECT LPAD(CUST_KEY,9,'0') || LPAD(HSE_SRVC_APLY_KEY,15,'0') as TNCY_AGRMT_BK,
SUM(RWVS.RENT_WVE_AMT) as RENT_WVE_AMT
FROM 
SOR_EMS_RWV_RENT_WVE_REC RWV, 
SOR_EMS_RWV_RENT_WVE_REC_STS RWVS
WHERE 
RWVS.RENT_WVE_EXRC_STS_CODE = 'A'
and RWV.rent_wve_key =RWVS.rent_wve_key
AND RWVS.RENT_WVE_TYPE_CODE IN ('1', '2', '3', '4', '6')
AND RWVS.RENT_WVE_BGN_DATE <= ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1)-1
AND RWVS.RENT_WVE_END_DATE  >= ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1)-1
AND RWVS.BGN_DATE <= TO_DATE('$$v_snsh_date', 'YYYYMMDD')
AND RWVS.END_DATE >= TO_DATE('$$v_snsh_date', 'YYYYMMDD')
GROUP BY LPAD(CUST_KEY,9,'0') || LPAD(HSE_SRVC_APLY_KEY,15,'0');

-- [SELECT] Step: read_LKP_RENT_FREE
-- Connection: SSA
SELECT LPAD(CUST_KEY,9,'0') || LPAD(HSE_SRVC_APLY_KEY,15,'0') as TNCY_AGRMT_BK, SUM(LVYS.RENT_FREE_AMT) as RENT_FREE_AMT
FROM 
SOR_EMS_RWV_LONG_VCNCY_REC LVY, 
SOR_EMS_RWV_LONG_VCNCY_REC_STS LVYS
WHERE LVYS.RENT_FREE_STS_CODE = 'S'
and 	LVYS.LONG_VCNCY_RENT_FREE_KEY = LVY.LONG_VCNCY_RENT_FREE_KEY
AND     LVYS.RENT_FREE_TYPE_CODE IN ('A')
AND     LVYS.RENT_FREE_BGN_DATE <= ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1)-1
AND     LVYS.RENT_FREE_END_DATE  >= ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1)-1
AND LVYS.BGN_DATE <= TO_DATE('$$v_snsh_date', 'YYYYMMDD')
AND LVYS.END_DATE >= TO_DATE('$$v_snsh_date', 'YYYYMMDD')
GROUP BY   LPAD(CUST_KEY,9,'0') || LPAD(HSE_SRVC_APLY_KEY,15,'0');

-- [SELECT] Step: read_LKP_EST_KEY
-- Connection: SSA
select est_key AS EST_KEY, 
TNCY_AGRMT_BK as TNCY_AGRMT_BK
from sor_hsm_unit u, 
sor_hsm_blk b, 
sor_ems_tam_tncy_agrmt ta,
sor_ems_tam_tncy_agrmt_STS ta2
where ta.tncy_agrmt_key = ta2.tncy_agrmt_key
and ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1)-1 between TA2.bgn_date and TA2.end_date
and  u.blk_key = b.blk_key
and u.unit_key = ta2.unit_key;

