select /*+ordered*/
sor_isp_extl_user_sts.cust_tnt_code,
sor_isp_extl_adt_trl.SYS_RPT_YEAR,
sor_isp_extl_adt_trl.SYS_RPT_MTH,
--sor_isp_extl_adt_trl.ADT_DATE,
sor_isp_extl_adt_trl.PRCS_ID,
sor_isp_extl_adt_trl.USER_ID,
sor_isp_extl_adt_trl.USER_ROLE_ID,
sor_isp_extl_adt_trl.RSRC_BNDL_ID,
sor_isp_extl_adt_trl.RSRC_BNDL_DESP,
sor_isp_extl_adt_trl.SYS_CODE,
sor_isp_extl_adt_trl.ADT_ACT_CODE,
sor_isp_extl_adt_trl.ADT_ACT_SVTY_CODE,
sor_isp_extl_adt_trl.ADT_ACT_DESP,
sor_isp_extl_adt_trl.ADT_AUX_INFO_TEXT,
sor_isp_extl_adt_trl.REMT_IP_ADDR,
sor_isp_extl_adt_trl.LAST_REC_TXN_TYPE_CODE
--sor_isp_extl_adt_trl.LAST_REC_TXN_DATE,
--sor_isp_extl_adt_trl.LAST_REC_TXN_USER_ID
from 
sor_isp_extl_adt_trl,
sor_isp_extl_user,
sor_isp_extl_user_sts
where 
sor_isp_extl_adt_trl.user_id = sor_isp_extl_user.user_id
and sor_isp_extl_user.ISP_EXTL_USER_KEY = sor_isp_extl_user_sts.ISP_EXTL_USER_KEY
and last_day(to_date('$$v_rpt_mth' || '01' ,'yyyymmdd')) between sor_isp_extl_user_sts.bgn_date and sor_isp_extl_user_sts.end_date;

-- [SELECT] Step: read_LKP_SOR_EMS_ELP_CUST_RGSTR
-- Connection: SSA
select
SOR_EMS_CPM_CUST_APLY.cust_key as CUST_KEY,
SOR_EMS_CPM_CUST_APLY.hse_srvc_aply_key AS HSE_SRVC_APLY_KEY,
SOR_EMS_ELP_CUST_RGSTR.cust_tnt_code AS CUST_TNT_CODE
from  
SOR_EMS_ELP_CUST_RGSTR,
SOR_EMS_ELP_CUST_RGSTR_STS,
(
select 
cust_tnt_code,max(CUST_TNT_CODE_BGN_DATE) AS CUST_TNT_CODE_BGN_DATE 
from 
SOR_EMS_ELP_CUST_RGSTR,
SOR_EMS_ELP_CUST_RGSTR_STS
WHERE
SOR_EMS_ELP_CUST_RGSTR.ELP_CUST_RGSTR_KEY = SOR_EMS_ELP_CUST_RGSTR_STS.ELP_CUST_RGSTR_KEY
AND last_day(TO_DATE('$$v_rpt_mth' || '01','yyyymmdd')) between bgn_date and end_date
group by cust_tnt_code
) max_cust_tnt_code,
SOR_EMS_CPM_CUST_APLY
where 
SOR_EMS_CPM_CUST_APLY.CUST_APLY_KEY = SOR_EMS_ELP_CUST_RGSTR.CUST_APLY_KEY
AND SOR_EMS_ELP_CUST_RGSTR.ELP_CUST_RGSTR_KEY = SOR_EMS_ELP_CUST_RGSTR_STS.ELP_CUST_RGSTR_KEY
AND last_day(TO_DATE('$$v_rpt_mth' || '01','yyyymmdd')) between bgn_date and end_date
AND SOR_EMS_ELP_CUST_RGSTR.CUST_TNT_CODE = max_cust_tnt_code.CUST_TNT_CODE
AND  SOR_EMS_ELP_CUST_RGSTR_STS.CUST_TNT_CODE_BGN_DATE = max_cust_tnt_code.CUST_TNT_CODE_BGN_DATE;

