-- [SELECT] Step: read_LKP_SOR_EMS_ELP_CUST_RGSTR
-- Connection: SSA
select 
SOR_EMS_ELP_CUST_RGSTR.cust_key as CUST_KEY,
SOR_EMS_ELP_CUST_RGSTR.hse_srvc_aply_key AS HSE_SRVC_APLY_KEY,
SOR_EMS_ELP_CUST_RGSTR.cust_tnt_code AS CUST_TNT_CODE
from  
SOR_EMS_ELP_CUST_RGSTR,
SOR_EMS_ELP_CUST_RGSTR_STS,
(
select 
cust_tnt_code,max(CUST_TNT_CODE_BGN_DATE) AS CUST_TNT_CODE_BGN_DATE 
from 
SOR_EMS_ELP_CUST_RGSTR,
SOR_EMS_ELP_CUST_RGSTR_STS
WHERE
SOR_EMS_ELP_CUST_RGSTR.ELP_CUST_RGSTR_KEY = SOR_EMS_ELP_CUST_RGSTR_STS.ELP_CUST_RGSTR_KEY
AND last_day(TO_DATE('$$v_rpt_mth' || '01','yyyymmdd')) between bgn_date and end_date
group by cust_tnt_code
) max_cust_tnt_code
where 
SOR_EMS_ELP_CUST_RGSTR.ELP_CUST_RGSTR_KEY = SOR_EMS_ELP_CUST_RGSTR_STS.ELP_CUST_RGSTR_KEY
AND last_day(TO_DATE('$$v_rpt_mth' || '01','yyyymmdd')) between bgn_date and end_date
AND SOR_EMS_ELP_CUST_RGSTR.CUST_TNT_CODE = max_cust_tnt_code.CUST_TNT_CODE
AND  SOR_EMS_ELP_CUST_RGSTR_STS.CUST_TNT_CODE_BGN_DATE = max_cust_tnt_code.CUST_TNT_CODE_BGN_DATE;

