-- [SOURCE_QUALIFIER] Step: apply_SQ_LRS_MTH_LTNG_RTN_STAT
SELECT 
LRS_COST_CTR.HSE_EST_CODE, 
LRS_COST_CTR.HSE_EST_TYPE_CODE, 
LRS_COST_CTR.HSE_BLDG_TYPE_CODE, 
LRS_BSNS_ACTV.PART_CODE, 
LRS_MTH_LTNG_RTN_STAT.LTNG_RTN_STAT_YEAR_MTH, 
LRS_MTH_LTNG_RTN_STAT.PRPTY_LET_UNIT_RENT_AMT, 
LRS_MTH_LTNG_RTN_STAT.CUR_RENT_ARR_CF_AMT, 
LRS_MTH_LTNG_RTN_STAT.SCND_RENT_ARR_CF_AMT, 
LRS_MTH_LTNG_RTN_STAT.THRD_RENT_ARR_CF_AMT, 
LRS_MTH_LTNG_RTN_STAT.FRTH_RENT_ARR_CF_AMT, 
LRS_MTH_LTNG_RTN_STAT.RENT_ARR_PND_WRTF_AMT 
FROM
LRS_MTH_LTNG_RTN_STAT
LEFT JOIN LRS_COST_CTR  ON LRS_MTH_LTNG_RTN_STAT.COST_CTR_CODE = LRS_COST_CTR.COST_CTR_CODE 
LEFT JOIN LRS_BSNS_ACTV ON LRS_MTH_LTNG_RTN_STAT.BSNS_ACTV_CODE = LRS_BSNS_ACTV.BSNS_ACTV_CODE
where substr(LTNG_RTN_STAT_YEAR_MTH,1,4) = substr('$$v_rpt_mth',1,4) and substr(LTNG_RTN_STAT_YEAR_MTH,-2) = substr('$$v_rpt_mth',-2);

