	SOR_HSM_UNIT.UNIT_TYPE_CODE,
	nvl(SOR_EMS_MRRS_EXTNT_OSTD_DEBT.FRST_EXTNT_OSTD_DEBT_AMT,0) as AMT1,
	nvl(SOR_EMS_MRRS_EXTNT_OSTD_DEBT.SCND_EXTNT_OSTD_DEBT_AMT,0) as AMT2,
	nvl(SOR_EMS_MRRS_EXTNT_OSTD_DEBT.THRD_EXTNT_OSTD_DEBT_AMT,0) as AMT3,
	nvl(SOR_EMS_MRRS_EXTNT_OSTD_DEBT.FRTH_EXTNT_OSTD_DEBT_AMT,0) as AMT4,
	SOR_EMS_MRRS_EXTNT_OSTD_DEBT.CUST_KEY, 
	SOR_EMS_MRRS_EXTNT_OSTD_DEBT.HSE_SRVC_APLY_KEY
FROM
