	nvl(SOR_EMS_MRRS_UAO_FEE_OSTD_DEBT.FRST_UAO_OSTD_DEBT_CF_AMT,0) as AMT1,
	nvl(SOR_EMS_MRRS_UAO_FEE_OSTD_DEBT.SCND_UAO_OSTD_DEBT_CF_AMT,0) as AMT2,
	nvl(SOR_EMS_MRRS_UAO_FEE_OSTD_DEBT.THRD_UAO_OSTD_DEBT_CF_AMT,0) as AMT3,
	0 as AMT4,
	SOR_EMS_MRRS_UAO_FEE_OSTD_DEBT.CUST_KEY, 
	SOR_EMS_MRRS_UAO_FEE_OSTD_DEBT.HSE_SRVC_APLY_KEY
FROM
      	SOR_EMS_TAM_TNCY_AGRMT,
      SOR_EMS_TAM_TNCY_AGRMT_STS,
	SOR_EMS_MRRS_UAO_FEE_OSTD_DEBT, 
	SOR_HSM_UNIT,
	SOR_HSM_BLK,
	SOR_RVC_COST_CTR_GRP,
	SOR_RVC_COST_CTR
WHERE
	LPAD(SOR_EMS_MRRS_UAO_FEE_OSTD_DEBT.CUST_KEY,9,'0') || LPAD(SOR_EMS_MRRS_UAO_FEE_OSTD_DEBT.HSE_SRVC_APLY_KEY,15,'0') = SOR_EMS_TAM_TNCY_AGRMT.TNCY_AGRMT_BK
	AND SOR_EMS_TAM_TNCY_AGRMT.TNCY_AGRMT_KEY = SOR_EMS_TAM_TNCY_AGRMT_STS.TNCY_AGRMT_KEY
       AND SOR_EMS_TAM_TNCY_AGRMT_STS.UNIT_KEY = SOR_HSM_UNIT.UNIT_KEY
	AND SOR_HSM_UNIT.BLK_KEY=SOR_HSM_BLK.BLK_KEY
	AND SOR_HSM_UNIT.BLK_KEY=SOR_RVC_COST_CTR_GRP.BLK_KEY
	AND SOR_RVC_COST_CTR_GRP.COST_CTR_KEY=SOR_RVC_COST_CTR.COST_CTR_KEY
	AND ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1)-1 BETWEEN SOR_RVC_COST_CTR_GRP.BGN_DATE AND SOR_RVC_COST_CTR_GRP.END_DATE
	AND ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1)-1 BETWEEN SOR_EMS_TAM_TNCY_AGRMT_STS.BGN_DATE AND SOR_EMS_TAM_TNCY_AGRMT_STS.END_DATE
	AND SOR_EMS_MRRS_UAO_FEE_OSTD_DEBT.SYS_RPT_YEAR=SUBSTR('$$v_rpt_mth',1,4)
	AND SOR_EMS_MRRS_UAO_FEE_OSTD_DEBT.SYS_RPT_MTH=SUBSTR('$$v_rpt_mth',5,2)
	AND SOR_RVC_COST_CTR_GRP.COST_CTR_TYPE_CODE<>'TPS'
union all
SELECT /*+ordered*/
	SOR_EMS_MRRS_MSN_OSTD_DEBT.SYS_RPT_YEAR, 
	SOR_EMS_MRRS_MSN_OSTD_DEBT.SYS_RPT_MTH, 
	SOR_RVC_COST_CTR.COST_CTR_KEY, 
	SOR_HSM_BLK.EST_KEY,
	SOR_HSM_UNIT.UNIT_TYPE_CODE,
	nvl(SOR_EMS_MRRS_MSN_OSTD_DEBT.FRST_EXCUST_OSTD_DEBT_AMT,0) as AMT1,
	nvl(SOR_EMS_MRRS_MSN_OSTD_DEBT.SCND_EXCUST_OSTD_DEBT_AMT,0) as AMT2,
	nvl(SOR_EMS_MRRS_MSN_OSTD_DEBT.THRD_EXCUST_OSTD_DEBT_AMT,0) as AMT3,
	0 as AMT4,
	SOR_EMS_MRRS_MSN_OSTD_DEBT.CUST_KEY, 
	SOR_EMS_MRRS_MSN_OSTD_DEBT.HSE_SRVC_APLY_KEY
FROM
      	SOR_EMS_TAM_TNCY_AGRMT,
      SOR_EMS_TAM_TNCY_AGRMT_STS,
	SOR_EMS_MRRS_MSN_OSTD_DEBT, 
	SOR_HSM_UNIT,
	SOR_HSM_BLK,
	SOR_RVC_COST_CTR_GRP,
	SOR_RVC_COST_CTR
WHERE
	LPAD(SOR_EMS_MRRS_MSN_OSTD_DEBT.CUST_KEY,9,'0') || LPAD(SOR_EMS_MRRS_MSN_OSTD_DEBT.HSE_SRVC_APLY_KEY,15,'0') = SOR_EMS_TAM_TNCY_AGRMT.TNCY_AGRMT_BK
	AND SOR_EMS_TAM_TNCY_AGRMT.TNCY_AGRMT_KEY = SOR_EMS_TAM_TNCY_AGRMT_STS.TNCY_AGRMT_KEY
       AND SOR_EMS_TAM_TNCY_AGRMT_STS.UNIT_KEY = SOR_HSM_UNIT.UNIT_KEY
	AND SOR_HSM_UNIT.BLK_KEY=SOR_HSM_BLK.BLK_KEY
	AND SOR_HSM_UNIT.BLK_KEY=SOR_RVC_COST_CTR_GRP.BLK_KEY
	AND SOR_RVC_COST_CTR_GRP.COST_CTR_KEY=SOR_RVC_COST_CTR.COST_CTR_KEY
	AND ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1)-1 BETWEEN SOR_RVC_COST_CTR_GRP.BGN_DATE AND SOR_RVC_COST_CTR_GRP.END_DATE
	AND ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1)-1 BETWEEN SOR_EMS_TAM_TNCY_AGRMT_STS.BGN_DATE AND SOR_EMS_TAM_TNCY_AGRMT_STS.END_DATE
	AND SOR_EMS_MRRS_MSN_OSTD_DEBT.SYS_RPT_YEAR=SUBSTR('$$v_rpt_mth',1,4)
	AND SOR_EMS_MRRS_MSN_OSTD_DEBT.SYS_RPT_MTH=SUBSTR('$$v_rpt_mth',5,2)
	AND SOR_RVC_COST_CTR_GRP.COST_CTR_TYPE_CODE<>'TPS')
group by 	
