-- [SELECT] Step: read_LKP_SOR_EMS_TAM_TNCY_AGRMT_STS
-- Connection: SOR
select	
	TNCY_AGRMT_BK as TNCY_AGRMT_BK, 
	max(TNCY_AGRMT_TM_STS_CODE) as TNCY_AGRMT_TM_STS_CODE,
	max(RENT_RVW_CATG_CODE) as RENT_RVW_CATG_CODE,
	max(RENT_FCTR_CODE) as RENT_FCTR_CODE,
	max(TNCY_AGRMT_CMNC_DATE) as TNCY_AGRMT_CMNC_DATE,
	max(TNCY_AGRMT_TM_TRMT_DATE) as TNCY_AGRMT_TM_TRMT_DATE
from (
select 
tncy_agrmt_Bk AS TNCY_AGRMT_BK, 	
null as TNCY_AGRMT_TM_STS_CODE,
null as RENT_RVW_CATG_CODE, 
RENT_FCTR_CODE as RENT_FCTR_CODE,
null as TNCY_AGRMT_CMNC_DATE,
null as TNCY_AGRMT_TM_TRMT_DATE
from sor_ems_tam_tncy_agrmt t,
sor_ems_tam_tncy_agrmt_sts t1,(
select tncy_agrmt_key, max(end_date) as end_date
from sor_ems_tam_tncy_agrmt_sts
where ( to_date($$v_snsh_date,'yyyymmdd') > end_date or  to_date($$v_snsh_date,'yyyymmdd') between bgn_date and end_date) and 
rent_bgn_date <= add_months(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1
group by tncy_agrmt_key) t2
where t.tncy_agrmt_key = t1.tncy_agrmt_key and
t2.tncy_agrmt_key = t1.tncy_agrmt_key and t2.end_date = t1.end_date
union all
select 
tncy_agrmt_Bk AS TNCY_AGRMT_BK, 	
null as TNCY_AGRMT_TM_STS_CODE,
RENT_RVW_CATG_CODE as RENT_RVW_CATG_CODE, 
null as RENT_FCTR_CODE,
null as TNCY_AGRMT_CMNC_DATE,
null as TNCY_AGRMT_TM_TRMT_DATE
from sor_ems_tam_tncy_agrmt t,
sor_ems_tam_tncy_agrmt_sts t1,(
select tncy_agrmt_key, max(end_date) as end_date
from sor_ems_tam_tncy_agrmt_sts
where ( to_date($$v_snsh_date,'yyyymmdd') > end_date or  to_date($$v_snsh_date,'yyyymmdd') between bgn_date and end_date) and 
RENT_RVW_CATG_bgn_date <= add_months(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1
group by tncy_agrmt_key) t2
where t.tncy_agrmt_key = t1.tncy_agrmt_key and
t2.tncy_agrmt_key = t1.tncy_agrmt_key and t2.end_date = t1.end_date
union all
SELECT  
	TNCY_AGRMT_BK as TNCY_AGRMT_BK,
	SOR_EMS_TAM_TNCY_AGRMT_STS.TNCY_AGRMT_TM_STS_CODE as TNCY_AGRMT_TM_STS_CODE,
	null as RENT_RVW_CATG_CODE, 	
	null as RENT_FCTR_CODE,
	SOR_EMS_TAM_TNCY_AGRMT_STS.TNCY_AGRMT_CMNC_DATE as TNCY_AGRMT_CMNC_DATE,
	SOR_EMS_TAM_TNCY_AGRMT_STS.TNCY_AGRMT_TM_TRMT_DATE as TNCY_AGRMT_TM_TRMT_DATE
FROM 
	SOR_EMS_TAM_TNCY_AGRMT,
	SOR_EMS_TAM_TNCY_AGRMT_STS
WHERE 
	SOR_EMS_TAM_TNCY_AGRMT.tncy_agrmt_key =	SOR_EMS_TAM_TNCY_AGRMT_STS.tncy_agrmt_key
and (TO_DATE('$$v_snsh_date', 'YYYYMMDD') ) BETWEEN SOR_EMS_TAM_TNCY_AGRMT_STS.BGN_DATE AND SOR_EMS_TAM_TNCY_AGRMT_STS.END_DATE 
) 
group by 
	TNCY_AGRMT_BK;

-- [SELECT] Step: read_mplt_LKP_ELD_MTH
-- Connection: source_db
SELECT
SOR_EMS_TAM_TNCY_AGRMT.TNCY_AGRMT_BK AS TNCY_AGRMT_BK,
  SUM(DECODE(SIGN(ADD_MONTHS(SOR_EMS_CPM_PTCL_STS.CUST_MBR_DOB_DATE, 720) - (ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1)-1)), 1, 0, 1)) AS ELD_CNT,
  COUNT(distinct SOR_EMS_CPM_CUST_APLY_MBR.CUST_APLY_MBR_KEY) AS HSHLD_SIZE,
SUM(CASE WHEN (SOR_EMS_CPM_PTCL_STS.CUST_MBR_GNDR_CODE = 'M') THEN 1 ELSE 0 END) AS HSHLD_MALE_MBR_CNT,
SUM(CASE WHEN (SOR_EMS_CPM_PTCL_STS.CUST_MBR_GNDR_CODE = 'F') THEN 1 ELSE 0 END) AS HSHLD_FML_MBR_CNT,
SUM(CASE WHEN (SOR_EMS_CPM_PTCL_STS.CUST_MBR_GNDR_CODE = 'U' OR SOR_EMS_CPM_PTCL_STS.CUST_MBR_GNDR_CODE IS NULL) THEN 1 ELSE 0 END) AS HSHLD_UNKWN_MBR_CNT,
SUM(CASE WHEN (sor_ems_cpm_dsbl.PTCL_KEY IS NOT NULL) THEN 1 ELSE 0 END) AS HSHLD_DSBL_MBR_CNT
FROM 
  SOR_EMS_TAM_TNCY_AGRMT,
  SOR_EMS_CPM_CUST_APLY,
  SOR_EMS_CPM_CUST_APLY_MBR,
  SOR_EMS_CPM_PTCL_STS, 
  SOR_EMS_CPM_CUST_APLY_MBR_STS,
 (select distinct PTCL_KEY from  sor_ems_cpm_dsbl,sor_ems_cpm_dsbl_sts where 
sor_ems_cpm_dsbl.dsbl_key=sor_ems_cpm_dsbl_sts.dsbl_key and
add_months(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1 BETWEEN sor_ems_cpm_dsbl_sts.BGN_DATE AND sor_ems_cpm_dsbl_sts.END_DATE) sor_ems_cpm_dsbl
WHERE
  (SOR_EMS_TAM_TNCY_AGRMT.CUST_KEY = SOR_EMS_CPM_CUST_APLY.CUST_KEY AND 
   SOR_EMS_TAM_TNCY_AGRMT.HSE_SRVC_APLY_KEY = SOR_EMS_CPM_CUST_APLY.HSE_SRVC_APLY_KEY)
  AND SOR_EMS_CPM_CUST_APLY_MBR.HSE_SRVC_APLY_TYPE_CODE = 'T'
  AND (SOR_EMS_CPM_CUST_APLY_MBR_STS.CUST_MBR_UP_IND = 'N' or SOR_EMS_CPM_CUST_APLY_MBR_STS.CUST_MBR_UP_IND is null)
  AND (SOR_EMS_CPM_CUST_APLY_MBR_STS.CUST_APLY_MBR_STS_CODE = 'A' OR SOR_EMS_CPM_CUST_APLY_MBR_STS.CUST_APLY_MBR_STS_CODE = 'T')
  AND SOR_EMS_CPM_CUST_APLY_MBR.CUST_APLY_MBR_KEY=SOR_EMS_CPM_CUST_APLY_MBR_STS.CUST_APLY_MBR_KEY
  AND add_months(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1 BETWEEN SOR_EMS_CPM_CUST_APLY_MBR_STS.BGN_DATE AND SOR_EMS_CPM_CUST_APLY_MBR_STS.END_DATE 
  AND add_months(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1 BETWEEN SOR_EMS_CPM_PTCL_STS.BGN_DATE AND SOR_EMS_CPM_PTCL_STS.END_DATE
  AND SOR_EMS_CPM_CUST_APLY.CUST_APLY_KEY=SOR_EMS_CPM_CUST_APLY_MBR.CUST_APLY_KEY
  AND SOR_EMS_CPM_CUST_APLY_MBR.PTCL_KEY=SOR_EMS_CPM_PTCL_STS.PTCL_KEY
  AND (sor_ems_cpm_dsbl.PTCL_KEY(+) = SOR_EMS_CPM_PTCL_STS.PTCL_KEY)
and SOR_EMS_CPM_PTCL_STS.CUST_MBR_DOB_DATE is not null
GROUP BY
  SOR_EMS_TAM_TNCY_AGRMT.TNCY_AGRMT_BK;

