-- =============================================================================

-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_EMS_TAM_TNCY_AGRMT_STS
SELECT 
	SOR_EMS_TAM_TNCY_AGRMT.TNCY_AGRMT_KEY as TNCY_AGRMT_KEY,
	SOR_EMS_TAM_TNCY_AGRMT.TNCY_AGRMT_BK as TNCY_AGRMT_BK,
      	SOR_EMS_TAM_TNCY_AGRMT_STS.ORIG_TNCY_AGRMT_CMNC_DATE AS ORIG_TNCY_AGRMT_CMNC_DATE,
     SOR_EMS_CPM_CUST_APLY_MBR.CUST_APLY_MBR_KEY AS CUST_APLY_MBR_KEY,
	to_number(substr('$$v_rpt_mth',5,2)) as SYS_RPT_MTH,
	to_number(substr('$$v_rpt_mth',1,4)) as SYS_RPT_YEAR,
	DSTR.DSTR_BRD_DSTR_CODE AS DSTR_BRD_DSTR_CODE,
	DSTR.DIS_EMMS_DSTR_KEY AS EMMS_DSTR_BRD_DSTR_KEY,
	DSTR.DSTR_CHC_DSTR_CODE AS DSTR_CHC_DSTR_CODE,
	DSTR.DCH_EMMS_DSTR_KEY AS EMMS_DSTR_CHC_DSTR_KEY,
	SOR_HSM_EST.EST_KEY as EST_KEY,
	SOR_HSM_EST.EST_CODE AS EST_CODE
FROM
      	SOR_EMS_TAM_TNCY_AGRMT,
      	SOR_EMS_TAM_TNCY_AGRMT_STS,
	SOR_EMS_CPM_CUST_APLY,
     SOR_EMS_CPM_CUST_APLY_MBR,
	SOR_HSM_UNIT,
	SOR_HSM_BLK,
	SOR_HSM_EST,
	SOR_EMS_HSM_PRH_EST_STS,
	(SELECT
DCH.UNIT_KEY AS UNIT_KEY,
DCH.DSTR_CHC_DSTR_CODE AS DSTR_CHC_DSTR_CODE,
DCH.EMMS_DSTR_KEY AS DCH_EMMS_DSTR_KEY,
DIS.DSTR_BRD_DSTR_CODE AS DSTR_BRD_DSTR_CODE,
DIS.EMMS_DSTR_KEY AS DIS_EMMS_DSTR_KEY
FROM (
SELECT 
UN.UNIT_KEY AS UNIT_KEY,
DSTR.DSTR_CODE AS DSTR_CHC_DSTR_CODE,
DSTR.EMMS_DSTR_KEY AS EMMS_DSTR_KEY
FROM 
SOR_HSM_UNIT UN,
SOR_HSM_BLK BLK,
SOR_HSM_EST EST,
SOR_HSM_EST_DSTR_RLTN EDR,
SOR_HSM_DSTR DSTR
WHERE 
UN.BLK_KEY = BLK.BLK_KEY AND 
BLK.EST_KEY = EST.EST_KEY AND
EST.EST_KEY = EDR.EST_KEY AND 
EDR.DSTR_KEY = DSTR.DSTR_KEY AND 
DSTR.DSTR_TYPE_CODE IN ('DCH')
and to_date('$$v_snsh_date', 'yyyymmdd') between edr.bgn_date and edr.end_date
--(UN.LAST_REC_TXN_TYPE_CODE IS NULL OR UN.LAST_REC_TXN_TYPE_CODE <> 'D')
) DCH
INNER JOIN (
SELECT
UN.UNIT_KEY AS UNIT_KEY,
DSTR.DSTR_CODE AS DSTR_BRD_DSTR_CODE,
DSTR.EMMS_DSTR_KEY AS EMMS_DSTR_KEY
FROM 
SOR_HSM_UNIT UN,
SOR_HSM_BLK BLK,
SOR_HSM_EST EST,
SOR_HSM_EST_DSTR_RLTN EDR,
SOR_HSM_DSTR DSTR
WHERE 
UN.BLK_KEY = BLK.BLK_KEY AND 
BLK.EST_KEY = EST.EST_KEY AND
EST.EST_KEY = EDR.EST_KEY AND 
EDR.DSTR_KEY = DSTR.DSTR_KEY AND 
DSTR.DSTR_TYPE_CODE IN ('DIS')
and to_date('$$v_snsh_date', 'yyyymmdd') between edr.bgn_date and edr.end_date
--(UN.LAST_REC_TXN_TYPE_CODE IS NULL OR UN.LAST_REC_TXN_TYPE_CODE <> 'D')
) DIS
ON DIS.UNIT_KEY = DCH.UNIT_KEY) DSTR
WHERE	SOR_EMS_TAM_TNCY_AGRMT_STS.UNIT_KEY=SOR_HSM_UNIT.UNIT_KEY
	AND SOR_HSM_UNIT.BLK_KEY=SOR_HSM_BLK.BLK_KEY
	AND SOR_HSM_EST.EST_KEY=SOR_HSM_BLK.EST_KEY
	AND SOR_EMS_HSM_PRH_EST_STS.EST_KEY = SOR_HSM_EST.EST_KEY
	--AND (SOR_HSM_UNIT.LAST_REC_TXN_TYPE_CODE is null or SOR_HSM_UNIT.LAST_REC_TXN_TYPE_CODE<>'D')
	--AND (SOR_HSM_BLK.LAST_REC_TXN_TYPE_CODE is null or SOR_HSM_BLK.LAST_REC_TXN_TYPE_CODE<>'D')
	--AND (SOR_HSM_EST.LAST_REC_TXN_TYPE_CODE is null or SOR_HSM_EST.LAST_REC_TXN_TYPE_CODE<>'D')
	--AND (SOR_EMS_HSM_PRH_EST_STS.LAST_REC_TXN_TYPE_CODE is null or SOR_EMS_HSM_PRH_EST_STS.LAST_REC_TXN_TYPE_CODE<>'D')
	AND SOR_EMS_TAM_TNCY_AGRMT.TNCY_AGRMT_KEY = SOR_EMS_TAM_TNCY_AGRMT_STS.TNCY_AGRMT_KEY
   	AND SOR_EMS_TAM_TNCY_AGRMT_STS.UNIT_KEY = DSTR.UNIT_KEY
	--AND (SOR_EMS_TAM_TNCY_AGRMT.LAST_REC_TXN_TYPE_CODE is null or SOR_EMS_TAM_TNCY_AGRMT.LAST_REC_TXN_TYPE_CODE<>'D')
	--AND add_months(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1 BETWEEN SOR_EMS_TAM_TNCY_AGRMT_STS.BGN_DATE AND SOR_EMS_TAM_TNCY_AGRMT_STS.END_DATE
	AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN SOR_EMS_TAM_TNCY_AGRMT_STS.BGN_DATE AND SOR_EMS_TAM_TNCY_AGRMT_STS.END_DATE
	AND SOR_EMS_TAM_TNCY_AGRMT.CUST_KEY = SOR_EMS_CPM_CUST_APLY.CUST_KEY 
	AND SOR_EMS_TAM_TNCY_AGRMT.HSE_SRVC_APLY_KEY = SOR_EMS_CPM_CUST_APLY.HSE_SRVC_APLY_KEY
	AND SOR_EMS_CPM_CUST_APLY.CUST_APLY_KEY = SOR_EMS_CPM_CUST_APLY_MBR.CUST_APLY_KEY
	AND add_months(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1 BETWEEN SOR_EMS_HSM_PRH_EST_STS.BGN_DATE AND SOR_EMS_HSM_PRH_EST_STS.END_DATE
AND SOR_EMS_TAM_TNCY_AGRMT_STS.TNCY_AGRMT_TM_STS_CODE IN ('A','I')
	AND TNCY_AGRMT_CMNC_DATE < add_months(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1
	AND (TNCY_AGRMT_TM_TRMT_DATE IS NULL OR TNCY_AGRMT_TM_TRMT_DATE >= add_months(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1);

-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_EMS_TAM_TNCY_AGRMT_SMRY
SELECT
	SOR_EMS_TAM_TNCY_AGRMT.TNCY_AGRMT_KEY
	, SOR_EMS_CPM_CUST_APLY_MBR.CUST_APLY_MBR_KEY AS CUST_APLY_MBR_KEY
	, FLOOR(MONTHS_BETWEEN(add_months(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1) - 1, SOR_EMS_CPM_PTCL_STS.CUST_MBR_DOB_DATE) / 12) as CUST_AGE
	, COUNT(distinct SOR_EMS_CPM_CUST_APLY_MBR.CUST_APLY_MBR_KEY) AS HSHLD_SIZE
	, SUM(CASE WHEN (SOR_EMS_CPM_PTCL_STS.CUST_MBR_GNDR_CODE = 'M') THEN 1 ELSE 0 END) AS HSHLD_MALE_MBR_CNT
	, SUM(CASE WHEN (SOR_EMS_CPM_PTCL_STS.CUST_MBR_GNDR_CODE = 'F') THEN 1 ELSE 0 END) AS HSHLD_FML_MBR_CNT
	, SUM(CASE WHEN (SOR_EMS_CPM_PTCL_STS.CUST_MBR_GNDR_CODE = 'U' OR SOR_EMS_CPM_PTCL_STS.CUST_MBR_GNDR_CODE IS NULL) THEN 1 ELSE 0 END) AS HSHLD_UNKWN_MBR_CNT
	, SUM(CASE WHEN (DSBL.PTCL_KEY IS NOT NULL) THEN 1 ELSE 0 END) AS HSHLD_DSBL_MBR_CNT
FROM 
	SOR_EMS_TAM_TNCY_AGRMT
	, SOR_EMS_CPM_CUST_APLY
	, SOR_EMS_CPM_CUST_APLY_MBR
	, SOR_EMS_CPM_PTCL_STS
	, SOR_EMS_CPM_CUST_APLY_MBR_STS
	, (select distinct PTCL_KEY from  sor_ems_cpm_dsbl,sor_ems_cpm_dsbl_sts where 
sor_ems_cpm_dsbl.dsbl_key=sor_ems_cpm_dsbl_sts.dsbl_key and
add_months(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1 BETWEEN sor_ems_cpm_dsbl_sts.BGN_DATE AND sor_ems_cpm_dsbl_sts.END_DATE) DSBL
WHERE
	(SOR_EMS_TAM_TNCY_AGRMT.CUST_KEY = SOR_EMS_CPM_CUST_APLY.CUST_KEY 
	AND SOR_EMS_TAM_TNCY_AGRMT.HSE_SRVC_APLY_KEY = SOR_EMS_CPM_CUST_APLY.HSE_SRVC_APLY_KEY)
	AND SOR_EMS_CPM_CUST_APLY_MBR.HSE_SRVC_APLY_TYPE_CODE = 'T'
	AND (SOR_EMS_CPM_CUST_APLY_MBR_STS.CUST_MBR_UP_IND = 'N' or SOR_EMS_CPM_CUST_APLY_MBR_STS.CUST_MBR_UP_IND is null)
	AND ((SOR_EMS_CPM_CUST_APLY_MBR_STS.CUST_APLY_MBR_STS_CODE = 'A')
	OR SOR_EMS_CPM_CUST_APLY_MBR_STS.CUST_APLY_MBR_STS_CODE = 'T')
	AND SOR_EMS_CPM_CUST_APLY_MBR.CUST_APLY_MBR_KEY=SOR_EMS_CPM_CUST_APLY_MBR_STS.CUST_APLY_MBR_KEY
	AND add_months(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1 BETWEEN SOR_EMS_CPM_CUST_APLY_MBR_STS.BGN_DATE AND SOR_EMS_CPM_CUST_APLY_MBR_STS.END_DATE 
	AND add_months(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1 BETWEEN SOR_EMS_CPM_PTCL_STS.BGN_DATE AND SOR_EMS_CPM_PTCL_STS.END_DATE
	AND SOR_EMS_CPM_CUST_APLY.CUST_APLY_KEY=SOR_EMS_CPM_CUST_APLY_MBR.CUST_APLY_KEY
	AND SOR_EMS_CPM_CUST_APLY_MBR.PTCL_KEY=SOR_EMS_CPM_PTCL_STS.PTCL_KEY
	AND (DSBL.PTCL_KEY(+) = SOR_EMS_CPM_PTCL_STS.PTCL_KEY)
GROUP BY
	SOR_EMS_TAM_TNCY_AGRMT.TNCY_AGRMT_KEY
	, SOR_EMS_CPM_CUST_APLY_MBR.CUST_APLY_MBR_KEY
	, FLOOR(MONTHS_BETWEEN(add_months(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1,SOR_EMS_CPM_PTCL_STS.CUST_MBR_DOB_DATE) / 12);

-- [SELECT] Step: read_mplt_LKP_SOR_EMS_TAM_TNCY_AGRMT_STS
-- Connection: SOR
select end_date as END_DATE, tncy_agrmt_KEY AS TNCY_AGRMT_KEY, 
RENT_FCTR_CODE as RENT_FCTR_CODE,
rent_bgn_date as RENT_BGN_DATE,
bgn_date as BGN_DATE
from sor_ems_tam_tncy_agrmt_sts
where ( to_date($$v_snsh_date,'yyyymmdd') > end_date or  to_date($$v_snsh_date,'yyyymmdd') between bgn_date and end_date);

