-- [SOURCE_QUALIFIER] Step: apply_DRP_EXCP
SELECT EXCP_PYMT_TXN_KEY, SWD_CASE_FILE_REF_NUM, DRP_TXN_VAL_DATE, DRP_PYMT_AMT, HSE_UNIT_KEY FROM SOR_EMS_CSA_DRP_EXCP_PYMT, SOR_EMS_CSA_DRP_EXCP_PYMT_STS WHERE SOR_EMS_CSA_DRP_EXCP_PYMT.EXCP_PYMT_TXN_KEY=SOR_EMS_CSA_DRP_EXCP_PYMT_STS.EXCP_PYMT_TXN_KEY AND substr(to_char(SOR_EMS_CSA_DRP_EXCP_PYMT.DRP_TXN_VAL_DATE, 'YYYYMMDD'), 1, 6) = $$v_rpt_mth
and SOR_EMS_CSA_DRP_EXCP_PYMT_STS.BGN_DATE <= ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1)-1
and SOR_EMS_CSA_DRP_EXCP_PYMT_STS.END_DATE >= ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1)-1;

-- [SOURCE_QUALIFIER] Step: apply_DRP
SELECT DRP_SWD_PYMT_KEY, SWD_CASE_FILE_REF_NUM, DRP_TXN_VAL_DATE, UNIT_KEY FROM SOR_EMS_CSA_DRP_SWD_PYMT, SOR_EMS_CSA_DRP_SWD_PYMT_STS WHERE SOR_EMS_CSA_DRP_SWD_PYMT.DRP_SWD_PYMT_KEY=SOR_EMS_CSA_DRP_SWD_PYMT_STS.DRP_SWD_PYMT_KEY AND substr(to_char(SOR_EMS_CSA_DRP_SWD_PYMT.drp_txn_val_date, 'YYYYMMDD'), 1, 6) = $$v_rpt_mth and SOR_EMS_CSA_DRP_SWD_PYMT_STS.BGN_DATE <= ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1)-1 and SOR_EMS_CSA_DRP_SWD_PYMT_STS.END_DATE >= ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1)-1;

-- [SOURCE_QUALIFIER] Step: apply_DIR_EXCP
SELECT DIR_PYMT_EXCP_KEY, SWD_DIR_PYMT_INTF_DATE, PRPL_CSSA_APLY_ID_TYPE_CODE, SWD_DIR_PYMT_AMT FROM SOR_EMS_CSA_SWD_PYMT_EXCP, SOR_EMS_CSA_SWD_PYMT_EXCP_STS WHERE SOR_EMS_CSA_SWD_PYMT_EXCP.DIR_PYMT_EXCP_KEY=SOR_EMS_CSA_SWD_PYMT_EXCP_STS.DIR_PYMT_EXCP_KEY AND substr(to_char(SOR_EMS_CSA_SWD_PYMT_EXCP.SWD_DIR_PYMT_INTF_DATE, 'YYYYMMDD'), 1, 6) = $$v_rpt_mth
and SOR_EMS_CSA_SWD_PYMT_EXCP_STS.BGN_DATE <= ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1)-1
and SOR_EMS_CSA_SWD_PYMT_EXCP_STS.END_DATE >= ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1)-1;

-- [SOURCE_QUALIFIER] Step: apply_DIR
SELECT DIR_PYMT_KEY, SWD_DIR_PYMT_INTF_DATE, HSE_UNIT_KEY FROM SOR_EMS_CSA_SWD_PYMT_ITEM, SOR_EMS_CSA_SWD_PYMT_ITEM_STS WHERE SOR_EMS_CSA_SWD_PYMT_ITEM.DIR_PYMT_KEY=SOR_EMS_CSA_SWD_PYMT_ITEM_STS.DIR_PYMT_KEY AND substr(to_char(SOR_EMS_CSA_SWD_PYMT_ITEM.SWD_DIR_PYMT_INTF_DATE, 'YYYYMMDD'), 1, 6) = $$v_rpt_mth
and SOR_EMS_CSA_SWD_PYMT_ITEM_STS.BGN_DATE <= ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1)-1
and SOR_EMS_CSA_SWD_PYMT_ITEM_STS.END_DATE >= ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1)-1;

