-- [SELECT] Step: read_LKP_EST_KEY_MBR_ID
-- Connection: SSA
SELECT SOR_HSM_BLK.EST_KEY as EST_KEY ,
substr(SOR_EMS_CPM_CUST_APLY_MBR.CUST_MBR_ID_NUM,1,7) as CUST_MBR_ID_NUM, SOR_EMS_CPM_CUST_APLY_MBR.CUST_MBR_ID_TYPE_CODE as CUST_MBR_ID_TYPE_CODE 
FROM 
SOR_EMS_TAM_TNCY_AGRMT, 
SOR_EMS_CPM_CUST_APLY, 
SOR_EMS_CPM_CUST_APLY_MBR, 
SOR_EMS_TAM_TNCY_AGRMT_STS,
sor_hsm_unit,
sor_hsm_blk
WHERE SOR_EMS_CPM_CUST_APLY.CUST_APLY_KEY = SOR_EMS_CPM_CUST_APLY_MBR.CUST_APLY_KEY
and SOR_EMS_CPM_CUST_APLY.CUST_KEY = SOR_EMS_TAM_TNCY_AGRMT.CUST_KEY 
and SOR_EMS_CPM_CUST_APLY.HSE_SRVC_APLY_KEY = SOR_EMS_TAM_TNCY_AGRMT.HSE_SRVC_APLY_KEY
and SOR_EMS_TAM_TNCY_AGRMT.TNCY_AGRMT_KEY = SOR_EMS_TAM_TNCY_AGRMT_STS.TNCY_AGRMT_KEY
and  sor_hsm_unit.blk_key = sor_hsm_blk.blk_key
and sor_hsm_unit.unit_key = SOR_EMS_TAM_TNCY_AGRMT_STS.unit_key
and ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1)-1 BETWEEN SOR_EMS_TAM_TNCY_AGRMT_STS.BGN_DATE AND SOR_EMS_TAM_TNCY_AGRMT_STS.END_DATE;

