-- [SELECT] Step: read_LKP_SOR_EMS_ELP_CUST_RGSTR
-- Connection: SSA
select 
SOR_EMS_ELP_CUST_RGSTR.cust_key as CUST_KEY,
SOR_EMS_ELP_CUST_RGSTR.hse_srvc_aply_key AS HSE_SRVC_APLY_KEY,
SOR_EMS_ELP_CUST_RGSTR.cust_tnt_code AS CUST_TNT_CODE
from  
SOR_EMS_ELP_CUST_RGSTR,
SOR_EMS_ELP_CUST_RGSTR_STS,
(
select 
cust_tnt_code,max(CUST_TNT_CODE_BGN_DATE) AS CUST_TNT_CODE_BGN_DATE 
from 
SOR_EMS_ELP_CUST_RGSTR,
SOR_EMS_ELP_CUST_RGSTR_STS
WHERE
SOR_EMS_ELP_CUST_RGSTR.ELP_CUST_RGSTR_KEY = SOR_EMS_ELP_CUST_RGSTR_STS.ELP_CUST_RGSTR_KEY
AND last_day(TO_DATE('$$v_rpt_mth' || '01','yyyymmdd')) between bgn_date and end_date
group by cust_tnt_code
) max_cust_tnt_code
where 
SOR_EMS_ELP_CUST_RGSTR.ELP_CUST_RGSTR_KEY = SOR_EMS_ELP_CUST_RGSTR_STS.ELP_CUST_RGSTR_KEY
AND last_day(TO_DATE('$$v_rpt_mth' || '01','yyyymmdd')) between bgn_date and end_date
AND SOR_EMS_ELP_CUST_RGSTR.CUST_TNT_CODE = max_cust_tnt_code.CUST_TNT_CODE
AND  SOR_EMS_ELP_CUST_RGSTR_STS.CUST_TNT_CODE_BGN_DATE = max_cust_tnt_code.CUST_TNT_CODE_BGN_DATE;

-- [SELECT] Step: read_LKP_EST_KEY_BY_TNCY_AGRMT_BK
-- Connection: SSA
SELECT 
SOR_EMS_TAM_TNCY_AGRMT.CUST_KEY AS CUST_KEY,
SOR_EMS_TAM_TNCY_AGRMT.HSE_SRVC_APLY_KEY AS HSE_SRVC_APLY_KEY,
SOR_HSM_BLK.EST_KEY AS EST_KEY 
FROM
SOR_EMS_TAM_TNCY_AGRMT,
SOR_EMS_TAM_TNCY_AGRMT_STS,
SOR_HSM_UNIT,
SOR_HSM_BLK
WHERE 
SOR_EMS_TAM_TNCY_AGRMT.TNCY_AGRMT_KEY = SOR_EMS_TAM_TNCY_AGRMT_STS.TNCY_AGRMT_KEY AND
TO_DATE('$$v_snsh_date','YYYYMMDD') BETWEEN SOR_EMS_TAM_TNCY_AGRMT_STS.BGN_DATE AND SOR_EMS_TAM_TNCY_AGRMT_STS.END_DATE AND
SOR_EMS_TAM_TNCY_AGRMT_STS.UNIT_KEY = SOR_HSM_UNIT.UNIT_KEY AND
SOR_HSM_UNIT.BLK_KEY = SOR_HSM_BLK.BLK_KEY;

-- [SELECT] Step: read_mplt_LKP_DDS_HRCHY_EMS_EST
-- Connection: target
SELECT 
DDS_HRCHY_EMS_EST.EST_SCD_KEY as EST_SCD_KEY, 
DDS_HRCHY_EMS_EST.RGN_KEY as RGN_KEY, 
DDS_HRCHY_EMS_EST.RGN_CODE as RGN_CODE, 
DDS_HRCHY_EMS_EST.RGN_ENG_NAME as RGN_ENG_NAME, 
DDS_HRCHY_EMS_EST.MGT_DSTR_KEY as MGT_DSTR_KEY, 
DDS_HRCHY_EMS_EST.MGT_DSTR_CODE as MGT_DSTR_CODE, 
DDS_HRCHY_EMS_EST.MGT_DSTR_ENG_NAME as MGT_DSTR_ENG_NAME, 
DDS_HRCHY_EMS_EST.DTMO_KEY as DTMO_KEY, 
DDS_HRCHY_EMS_EST.DTMO_CODE as DTMO_CODE, 
DDS_HRCHY_EMS_EST.DTMO_ENG_NAME as DTMO_ENG_NAME, 
DDS_HRCHY_EMS_EST.EST_CODE as EST_CODE, 
DDS_HRCHY_EMS_EST.EST_TYPE_CODE as EST_TYPE_CODE, 
DDS_HRCHY_EMS_EST.EST_ENG_NAME as EST_ENG_NAME, 
DDS_HRCHY_EMS_EST.EST_CHI_NAME as EST_CHI_NAME, 
DDS_HRCHY_EMS_EST.BGN_DATE as BGN_DATE, 
DDS_HRCHY_EMS_EST.END_DATE as END_DATE, DDS_HRCHY_EMS_EST.EST_KEY as EST_KEY 
FROM DDS_HRCHY_EMS_EST
WHERE add_months(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1 between DDS_HRCHY_EMS_EST.BGN_DATE AND DDS_HRCHY_EMS_EST.END_DATE;

